<script lang="ts">
 import {onMount} from 'svelte'; import RealMunicipalityControls from './RealMunicipalityControls.svelte'; import RealParkMap from './RealParkMap.svelte'; import RealParkDetails from './RealParkDetails.svelte';
 import type {AmenityCollection,AmenityFeature,CategoryWeightCollection,InvestigationSort,MunicipalityRealFilters,Persona,RealParkCollection,RealParkFeature} from '../types/municipality';
 import {booleanFor,defaultRealFilters,filterRealParks,formatNumber,incompleteField,parkName,personaOptions,realDatasetSummary,scoreField,sortInvestigationParks,valueFor} from '../lib/realMunicipality';
 let {drawerOpen,onCloseDrawer}:{drawerOpen:boolean;onCloseDrawer:()=>void}=$props();let parks=$state<RealParkFeature[]>([]);let amenities=$state<AmenityFeature[]>([]);let weights=$state<CategoryWeightCollection['features'][number]['properties'][]>([]);let persona=$state<Persona>('young');let filters=$state<MunicipalityRealFilters>({...defaultRealFilters});let investigationSort=$state<InvestigationSort>('priority');let selectedId=$state<string|null>(null);let loading=$state(true);let error=$state<string|null>(null);
 let matches=$derived(filterRealParks(parks,persona,filters));let sortedMatches=$derived(sortInvestigationParks(matches,persona,investigationSort));let selected=$derived(matches.find(p=>p.properties.park_id===selectedId)??null);let totals=$derived(realDatasetSummary(parks,persona));let personaLabel=$derived(personaOptions.find(p=>p.id===persona)?.label??persona);let scoreBands=$derived([['0–24',0,25],['25–49',25,50],['50–74',50,75],['75–100',75,101],['Unknown',null,null]] as const);
 const bandCount=(low:number|null,high:number|null)=>low===null?parks.filter(p=>valueFor(p,scoreField(persona))===null).length:parks.filter(p=>{const v=valueFor(p,scoreField(persona));return v!==null&&v>=low&&v<(high??101)}).length;
 $effect(()=>{if(selectedId&&!matches.some(p=>p.properties.park_id===selectedId))selectedId=null;});
 onMount(async()=>{try{const [parkResponse,weightResponse,amenityResponse]=await Promise.all([fetch('/data/lund-parks.geojson'),fetch('/data/category-weights.json'),fetch('/data/amenities.geojson')]);if(!parkResponse.ok||!weightResponse.ok||!amenityResponse.ok)throw new Error('Municipality data files could not be loaded.');const parkData=await parkResponse.json() as RealParkCollection;const weightData=await weightResponse.json() as CategoryWeightCollection;const amenityData=await amenityResponse.json() as AmenityCollection;if(parkData.features.length!==172)throw new Error(`Expected 172 parks but loaded ${parkData.features.length}.`);parks=parkData.features;weights=weightData.features.map(f=>f.properties);amenities=amenityData.features;}catch(reason){error=reason instanceof Error?reason.message:'Municipality data could not be loaded.'}finally{loading=false}});
</script>
<div class="municipality-view"><RealMunicipalityControls bind:persona bind:filters resultCount={matches.length} park={selected} open={drawerOpen} onClose={onCloseDrawer}/><section class="municipality-center"><header class="municipality-heading"><div><h1>Lund Park Insights</h1><p>Compare park quality and nearby demographics across Lund.</p></div></header><p class="provisional-banner">Scores are provisional and reflect available mapped and modelled evidence.</p>
{#if loading}<div class="municipality-loading">Loading 172 real park polygons…</div>{:else if error}<div class="municipality-error" role="alert"><strong>Data unavailable</strong><p>{error}</p></div>{:else}
 <div class="overview-intro"><strong>Overview — All assessed parks</strong><span>These indicators use all loaded records. Persona selection changes persona-based values; investigation filters do not.</span></div><section class="stat-cards real-stat-cards" aria-label="Overview of all assessed parks"><article><strong>{totals.total}</strong><div><span>Total parks assessed</span><small>All loaded polygons</small></div></article><article><strong>{formatNumber(totals.average)}</strong><div><span>Average {personaLabel} score</span><small>Known scores only</small></div></article><article><strong>{totals.incomplete}</strong><div><span>Parks with incomplete evidence</span><small>{personaLabel} evidence flag</small></div></article><article><strong>{totals.demographicAvailable}</strong><div><span>Demographic estimates available</span><small>300 m straight-line catchments</small></div></article><article><strong>{totals.demographicUnknown}</strong><div><span>Unknown demographics</span><small>No represented population data</small></div></article></section>
 <div class="municipality-map-wrap"><div class="filtered-count" aria-live="polite">Showing <strong>{matches.length}</strong> of <strong>{parks.length}</strong> parks</div><div class="municipality-map"><RealParkMap parks={matches} {amenities} {persona} selectedId={selectedId} onHover={()=>{}} onLeave={()=>{}} onSelect={(p)=>{selectedId=p.properties.park_id}}/></div></div>
 <div class="analysis-sections"><details><summary><span><strong>Park Characteristics Overview</strong><small>{personaLabel} score distribution across all assessed parks</small></span><span class="expand-label">Expand</span></summary><div class="analysis-content"><p class="scope-note">Based on all assessed parks</p><div class="score-bands">{#each scoreBands as band}<div><span>{band[0]}</span><div><i style:width={`${parks.length?bandCount(band[1],band[2])/parks.length*100:0}%`}></i></div><strong>{bandCount(band[1],band[2])}</strong></div>{/each}</div><p class="method-note">Evidence coverage is the proportion of intended evidence available; it is not a measure of score accuracy.</p></div></details>
 <details><summary><span><strong>Potential Areas for Investigation</strong><small>Evidence and demographics for {matches.length} matching parks</small></span><span class="expand-label">Expand</span></summary><section class="analysis-content opportunities"><p class="scope-note">Showing observations for {matches.length} matching parks</p><p>Exploratory indicators are not verified recommendations. Rank 1 means greatest potential priority; higher persona scores mean better modelled park quality.</p><label class="investigation-sort">Sort parks<select bind:value={investigationSort}><option value="priority">Demographic priority rank</option><option value="score">Selected persona score</option><option value="name">Park name</option></select></label>{#if matches.length===0}<p class="empty-list">No parks match the current investigation controls.</p>{:else}<div class="real-opportunity-list">{#each sortedMatches as park}<button class:selected={selectedId===park.properties.park_id} onclick={()=>selectedId=park.properties.park_id}><strong>{parkName(park)}</strong><span>Score {formatNumber(valueFor(park,scoreField(persona)))} · {booleanFor(park,incompleteField(persona))?'Incomplete evidence':'Complete evidence'} · Nearby population {formatNumber(park.properties.catchment_population,0)} · Priority rank {formatNumber(park.properties.demographic_priority_rank,0)}</span></button>{/each}</div>{/if}</section></details></div>
 <details class="limitations"><summary>Data interpretation and limitations</summary><ul><li>Tree cover is a proxy for potential shade.</li><li>Path-surface evidence does not establish wheelchair accessibility.</li><li>Surface-temperature cooling is not air temperature.</li><li>Nearby age shares are estimates, not observed visitors.</li><li>Demographic priority is exploratory, not a verified recommendation.</li></ul></details>
{/if}</section><RealParkDetails park={selected} {persona} {weights} pinned={selected!==null} onClose={()=>{selectedId=null}}/></div>
